def respond_to_enterprise(known_groups, insights, prices, quality_c):
    turns = rows("SELECT * FROM enterprise_turns ORDER BY message_id")
    latest_turns = {}
    for turn in turns:
        if safe_float(turn.get("closed")) == 0:
        latest_turns[turn.get("thread_id")] = turn
    actionable = [
        turn for turn in latest_turns.values()
        if safe_float(turn.get("closed")) == 0
        and turn.get("sender") in ("customer", "system")
        and safe_float(turn.get("message_id")) > 0
    ]
    if not actionable:
        return 0
    customer_ids = sorted({int(turn["customer_id"]) for turn in actionable})

